import itertools
n=0
for size in range(5):
 for keys in itertools.product('abc', repeat=size):
  for mask in range(8):
   strategy={k:4 for i,k in enumerate('abc') if mask>>i&1}
   def old():
    assert all(k in strategy for k in keys), ' ## Logic error, no quantization strategy for module'
   def new():
    for k in keys:
     assert k in strategy, f' ## Logic error, no quantization strategy for module {k}'
   results=[]
   for f in (old,new):
    try: f(); results.append((True,''))
    except AssertionError as e: results.append((False,str(e)))
   assert results[0][0]==results[1][0]
   if not results[1][0]: assert results[1][1].endswith(next(k for k in keys if k not in strategy))
   n+=1
print(f'{n} cases: identical pass/fail; new message identifies first missing key; includes empty sequences.')
